                                         <p className={`text-[11px] leading-relaxed line-clamp-2 ${!isRead ? 'text-slate-600 dark:text-slate-400 font-medium' : 'text-slate-500 dark:text-slate-500'}`}>{notif.desc}</p>
                                      </div>
