// --- SCHEMAS & MODELS ---
const userSchema = new mongoose.Schema({
  id: { type: String, unique: true }, 
  email: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  role: { type: String, default: 'user' },
  createdAt: { type: Number, default: Date.now },
  botSettings: {
    botName: { type: String, default: 'Trợ lý AI' },
    primaryColor: { type: String, default: '#8b5cf6' },
    welcomeMessage: { type: String, default: 'Xin chào! Tôi có thể giúp gì cho bạn?' },
    position: { type: String, default: 'right' },
    avatarUrl: { type: String, default: '' }
  },
  plugins: {
    autoOpen: { enabled: { type: Boolean, default: false }, delay: { type: Number, default: 5 } },
    social: { enabled: { type: Boolean, default: false }, zalo: String, phone: String },
    leadForm: { enabled: { type: Boolean, default: false }, title: String, trigger: String }
  }
});

const documentSchema = new mongoose.Schema({
  id: String,
  userId: String,
  name: String,
  content: String,
  type: String,
  status: String,
  createdAt: Number
});

const chatLogSchema = new mongoose.Schema({
  id: String,
  userId: String,
  customerSessionId: String,
  query: String,
  answer: String,
  timestamp: Number,
  tokens: Number,
  isSolved: Boolean
});

const leadSchema = new mongoose.Schema({
  id: String,
  userId: String,
  name: String,
  phone: String,
  email: String,
  source: String,
  status: String,
  createdAt: Number,
  isTest: Boolean
});

const notificationSchema = new mongoose.Schema({
  id: String,
  userId: String,
  title: String,
  desc: String,
  time: Number,
  scheduledAt: Number,
  readBy: [String],
  icon: String,
  color: String,
  bg: String
});

const directMessageSchema = new mongoose.Schema({
  id: String,
  senderId: String,
  receiverId: String,
  content: String,
  timestamp: Number,
  isRead: { type: Boolean, default: false },
  type: { type: String, default: 'text' }, // text, sticker, image
  replyToId: String,
  reactions: [{ userId: String, emoji: String }]
});

// Models
const User = mongoose.model('User', userSchema);
const Document = mongoose.model('Document', documentSchema);
const ChatLog = mongoose.model('ChatLog', chatLogSchema);
const Lead = mongoose.model('Lead', leadSchema);
const Notification = mongoose.model('Notification', notificationSchema);
const DirectMessage = mongoose.model('DirectMessage', directMessageSchema);

