                              lastMessageTime: Date.now(),
                              unreadCount: 0
                          };
                          setConversations(prev => [newConv, ...prev]);
                          setActiveChatUser(newConv);
                          if (onClearTargetUser) onClearTargetUser();
                      }
                  };
                  fetchTarget();
              }
          }
      }
  }, [initialChatUserId, conversations, user.role]);

