          id: tempId,
          senderId: user.id,
          receiverId: activeChatUser.id,
          content: msgContent,
          timestamp: Date.now(),
          isRead: false,
          type: msgType,
          replyToId: replyId,
          replyToContent: replyingTo ? (replyingTo.type === 'sticker' ? '[Sticker]' : (replyingTo.type === 'image' ? '[Hình ảnh]' : replyingTo.content)) : undefined,
          reactions: []
