      setMessages(prev => [...prev, tempMsg]);
      setNewMessage('');
      setReplyingTo(null);
      setShowStickerPicker(false);
      setShowEmojiPicker(false);

      try {
          await apiService.sendDirectMessage(user.id, activeChatUser.id, msgContent, msgType, replyId);
