app.get('/widget.js', (req, res) => {
  const scriptContent = `
(function() {
  if (window.BibiChatLoaded) return;
  window.BibiChatLoaded = true;

  var config = window.BibiChatConfig || {};
  var widgetId = config.widgetId;

  if (!widgetId) {
